    vu_jws(j);
    if (j->p < j->end && *j->p == '}') { j->p++; j->depth--; return 0; }
    if (!first) {
        if (j->p >= j->end || *j->p != ',') { vu_jfail(j, "expected ',' or '}'"); return -1; }
        j->p++;
        vu_jws(j);
    }
    if (!vu_jdec_Str(j, key)) return -1;
    vu_jws(j);
    if (j->p >= j->end || *j->p != ':') { drop_Str(key); vu_jfail(j, "expected ':'"); return -1; }
