static inline T_Scope *vu_at_L_S_Scope(L_S_Scope *l, int64_t i, int line) {
    /* one unsigned comparison: also catches i < 0, and measured faster than two signed ones (n-body 17%) */
    if (__builtin_expect((uint64_t)i >= (uint64_t)l->len, 0)) vu_oob(i, l->len, line);
    return &l->data[i];
}
/* A read in a tried loop (vu_vf_add in the runtime): out of range records a failure and reads a zero. */
/* (const after the element type: for a list of pointers, the pointers are what's const) */
static inline T_Scope const *vu_vfat_L_S_Scope(const L_S_Scope *l, int64_t i, uint64_t *f) {
    static T_Scope const zero;
    int in = (uint64_t)i < (uint64_t)l->len;
    *f |= (uint64_t)!in;
    return in ? &l->data[i] : &zero;
}
static void vu_grow_L_S_Scope(L_S_Scope *l) {
    if (l->cap > (int64_t)(PTRDIFF_MAX / sizeof(T_Scope) / 2)) vu_oom();
    int64_t c = l->cap ? l->cap * 2 : 4;
    T_Scope *d = (T_Scope *)realloc(l->data, (size_t)c * sizeof(T_Scope));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static void vu_reserve_L_S_Scope(L_S_Scope *l, int64_t n, int line) {
    if (n < 0) vu_fail(line, "reserve(%lld): the count can't be negative", (long long)n);
    if (n <= l->cap - l->len) return;
    if (n > (int64_t)(PTRDIFF_MAX / sizeof(T_Scope)) - l->len) vu_oom();
    int64_t c = l->len + n;
    T_Scope *d = (T_Scope *)realloc(l->data, (size_t)c * sizeof(T_Scope));
    if (!d) vu_oom();
    l->data = d;
    l->cap = c;
}
static inline T_Scope vu_pop_L_S_Scope(L_S_Scope *l, int line) {
    if (__builtin_expect(l->len == 0, 0)) vu_fail(line, "pop() from an empty list");
    return l->data[--l->len];
}
static inline void vu_push_L_S_Scope(L_S_Scope *l, T_Scope v) {
    if (l->len == l->cap) vu_grow_L_S_Scope(l);
    l->data[l->len++] = v;
}
static L_S_Scope vu_rep_L_S_Scope(L_S_Scope src, int64_t n, int line) {
    L_S_Scope r = {0};
    if (n > 0 && src.len > 0) {
        if (n > INT64_MAX / src.len || src.len * n > (int64_t)(PTRDIFF_MAX / sizeof(T_Scope)))
            vu_fail(line, "list of %lld x %lld elements is too large", (long long)src.len, (long long)n);
        int64_t total = src.len * n;
        r.data = (T_Scope *)vu_malloc((size_t)total * sizeof(T_Scope));
        r.len = r.cap = total;
        if (src.len == 1) { T_Scope v = src.data[0]; for (int64_t k = 0; k < total; k++) r.data[k] = v; }
        else for (int64_t k = 0; k < n; k++) memcpy(r.data + k * src.len, src.data, (size_t)src.len * sizeof(T_Scope));
    }
    free(src.data);
    return r;
}
