#define VU_NODE_Str (sizeof(vu_str) < 2 * sizeof(void *) ? 2 * sizeof(void *) : sizeof(vu_str))
static __thread vu_str *vu_free_Str;
static __thread int64_t vu_nfree_Str;   /* how many are on it (counted with several threads) */
/* Free nodes shared between threads (see vu_share_free): chunks, each a whole free list whose first
   node links the next chunk in its second word. */
static void *vu_chunks_Str;
static pthread_mutex_t vu_chunks_lock_Str = PTHREAD_MUTEX_INITIALIZER;
/* Takes up to VU_TAKE nodes from the first chunk (the rest of it stays shared), so that threads
   share a big list instead of one of them taking all of it. */
__attribute__((noinline)) static void vu_take_chunk_Str(void) {
    pthread_mutex_lock(&vu_chunks_lock_Str);
    char *c = (char *)vu_chunks_Str;
    if (c) {
        void *next_chunk, *rest;
        VU_UNPOISON(c, 2 * sizeof(void *));
        memcpy(&next_chunk, c + sizeof(void *), sizeof(void *));
        VU_POISON(c, 2 * sizeof(void *));
        char *p = c;
        for (int i = 1;; i++) {
            VU_UNPOISON(p, sizeof(void *));
            memcpy(&rest, p, sizeof(void *));
            if (!rest || i == VU_TAKE) {
                memset(p, 0, sizeof(void *));   /* p ends the list this thread takes */
                VU_POISON(p, sizeof(void *));
                break;
            }
            VU_POISON(p, sizeof(void *));
            p = (char *)rest;
        }
        if (rest) {
            VU_UNPOISON((char *)rest + sizeof(void *), sizeof(void *));
            memcpy((char *)rest + sizeof(void *), &next_chunk, sizeof(void *));
            VU_POISON((char *)rest + sizeof(void *), sizeof(void *));
            next_chunk = rest;
        }
        __atomic_store_n(&vu_chunks_Str, next_chunk, __ATOMIC_RELAXED);
        vu_free_Str = (vu_str *)c;
        vu_nfree_Str = VU_TAKE;   /* (at most; it only decides when to give some back) */
    }
    pthread_mutex_unlock(&vu_chunks_lock_Str);
}
static void vu_give_chunk_Str(void) {
    char *c = (char *)vu_free_Str;
    if (!c) return;
    pthread_mutex_lock(&vu_chunks_lock_Str);
    VU_UNPOISON(c + sizeof(void *), sizeof(void *));
    memcpy(c + sizeof(void *), &vu_chunks_Str, sizeof(void *));
    VU_POISON(c + sizeof(void *), sizeof(void *));
    __atomic_store_n(&vu_chunks_Str, (void *)c, __ATOMIC_RELAXED);
    pthread_mutex_unlock(&vu_chunks_lock_Str);
    vu_free_Str = NULL;
    vu_nfree_Str = 0;
}
static vu_pool vu_pool_Str = { vu_give_chunk_Str, NULL };
__attribute__((constructor)) static void vu_pool_init_Str(void) { vu_pool_Str.next = vu_pools; vu_pools = &vu_pool_Str; }
static inline vu_str *vu_box_Str(vu_str v) {
#ifdef VU_MALLOC
    vu_str *p = (vu_str *)vu_malloc(sizeof(vu_str));
#else
#if defined(_OPENMP) || defined(VU_MT)
    if (!vu_free_Str && __atomic_load_n(&vu_chunks_Str, __ATOMIC_RELAXED)) vu_take_chunk_Str();
#endif
    vu_str *p = vu_free_Str;
    if (p) {
        VU_UNPOISON(p, VU_NODE_Str);
        memcpy(&vu_free_Str, p, sizeof(void *));
#if defined(_OPENMP) || defined(VU_MT)
        vu_nfree_Str--;
#endif
    }
    else p = (vu_str *)vu_bump(VU_NODE_Str);
#endif
    *p = v;
    return p;
}
static inline void vu_release_Str(vu_str *p) {
#ifdef VU_MALLOC
    free(p);
#else
    memcpy(p, &vu_free_Str, sizeof(void *));
    vu_free_Str = p;
    VU_POISON(p, VU_NODE_Str);   /* any later access to this freed node is reported */
#if defined(_OPENMP) || defined(VU_MT)
    /* nodes made on other threads and freed here (a task receiving values from another thread)
       would pile up on this list: past a limit the list goes to the shared pool */
    if (++vu_nfree_Str >= 4 * VU_TAKE) vu_give_chunk_Str();
#endif
#endif
}
